## Key Concepts
- Per-region traffic shaping, backpressure, local buffering
- Idempotent delivery and deduplication
- Fast-path caching and back-off strategies
- Canary deployments, runbooks, and rollback criteria

## Code Example
```javascript
// Simple idempotent delivery using Redis
const redis = require('redis');
const client = redis.createClient();

async function deliver(msgId, payload) {
  const key = `notif:${msgId}`;
  return new Promise((resolve, reject) => {
    client.setnx(key, 1, (err, res) => {
      if (err) return reject(err);
      if (res === 1) {
        client.expire(key, 3600, () => resolve(smsGateway.send(payload)));
      } else {
        resolve("duplicate");
      }
    });
  });
}
```

